#!/bin/sh
# P132: `x % 2^k == 0` / `!= 0` (compiler/src/core/qbe.pion,
# qbe_try_emit_mod_pow2_eq_zero) and `break` / `continue` outside a loop body
# (compiler/src/core/types.pion).
#   1. modpow.pion (generated by gen.py, reference output computed in Python):
#      every power-of-two divisor each of Byte / Int8 / Int / UInt / Int64 /
#      UInt64 can spell, over all 256 Byte and Int8 values and boundary values
#      of the wider types, in `if` conditions and value contexts (Byte
#      divisors are `b'\xNN'` literals, which take the general `%` path); the
#      operand of the test (a call with side effects, also returning Int8 /
#      Byte) is evaluated exactly once.
#   2. loops.pion: `break` / `continue` in a nested C-style `for` `init`, in
#      `for ... in` range bounds and in a `for x in` iterable leave / continue
#      the enclosing loop (with owned String temporaries there), and a loop
#      nested in a `while` condition breaks itself. edge.pion: an operand of
#      the test that leaves the function inside a value-context comparison
#      (right side `||` / `if`), and `continue` / `break` in a nested `for`
#      `init` under range / array / `while` outer loops.
#   For these three, dev and --release (each build in its own empty
#   PION_CACHE_DIR): exact stdout, exit 0 and empty stderr natively, with an
#   AddressSanitizer runtime (LeakSanitizer on Linux) and on Wasm32.
#   divzero.pion: divisors the operand's width narrows to 0 (Int8 `% 256`,
#   UInt `% 4294967296U`) are not folded: `#verify` panics with "division by
#   zero" (native and Wasm32); plain code behaves exactly like the same `%`
#   through a variable divisor on the same target (ARM64 does not trap).
#   3. `pionc check --json` rejects `break` / `continue` outside a loop body:
#      a function body, a `while` condition and a C-style `for` condition /
#      step (outermost and nested), and a closure inside a loop, with "cannot
#      use `break` outside a loop" (E_TYPE_MISMATCH); loops.pion is accepted.
set -eu

PIONC="${1:?usage: run_e2e.sh <pionc>}"
ROOT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")/../../.." && pwd)
DIR="$ROOT_DIR/tests/e2e/p132_mod_pow2_loop_break"
WASM_RT="$ROOT_DIR/runtime/pion_wasm_rt.mjs"
unset PION_TARGET || true
TMP_DIR=$(mktemp -d)
trap 'rm -rf "$TMP_DIR"' EXIT
CC_BIN="${CC:-cc}"

fresh_cas() {
  PION_CACHE_DIR=$(mktemp -d "$TMP_DIR/cas.XXXXXX")
  export PION_CACHE_DIR
}

# check <label> <reference> <out> <err> <exit status>
check() {
  if [ "$5" -ne 0 ]; then
    cat "$4" >&2
    echo "FAIL: p132 $1 exited $5" >&2
    exit 1
  fi
  if [ -s "$4" ]; then
    cat "$4" >&2
    echo "FAIL: p132 $1 wrote to stderr" >&2
    exit 1
  fi
  if [ ! -s "$2" ] || [ ! -s "$3" ] || ! cmp -s "$2" "$3"; then
    diff -u "$2" "$3" >&2 || true
    echo "FAIL: p132 $1 stdout differs from the reference (or is empty)" >&2
    exit 1
  fi
}

python3 -E "$DIR/gen.py" "$TMP_DIR"
[ "$(wc -l < "$TMP_DIR/modpow.expected")" -eq 7 ] || { echo "FAIL: p132 gen.py reference" >&2; exit 1; }
cp "$DIR/loops.pion" "$DIR/loops.expected" "$DIR/edge.pion" "$DIR/edge.expected" "$TMP_DIR/"

ASAN=0
if CC="$CC_BIN" sh "$ROOT_DIR/scripts/san-rt.sh" address "$TMP_DIR/libpionrt_asan.a"; then
  ASAN=1
elif [ "${PION_REQUIRE_SANITIZERS:-0}" = "1" ]; then
  echo "FAIL: p132 ASan required by PION_REQUIRE_SANITIZERS=1" >&2
  exit 1
fi
if [ "$(uname -s)" = "Darwin" ]; then
  ASAN_OPTS="detect_leaks=0:halt_on_error=1"
else
  ASAN_OPTS="detect_leaks=1:halt_on_error=1"
fi
HAVE_NODE=0
command -v node >/dev/null 2>&1 && HAVE_NODE=1

N=0
for PROG in modpow loops edge; do
  SRC="$TMP_DIR/$PROG.pion"
  REF="$TMP_DIR/$PROG.expected"
  for MODE in dev release; do
    FLAG=""
    [ "$MODE" = "release" ] && FLAG="--release"
    BASE="$TMP_DIR/${PROG}_$MODE"
    fresh_cas
    "$PIONC" build $FLAG -o "$BASE" "$SRC"
    set +e
    "$BASE" > "$BASE.out" 2> "$BASE.err"
    RC=$?
    set -e
    check "$PROG $MODE native" "$REF" "$BASE.out" "$BASE.err" "$RC"
    LEGS="native"
    if [ "$ASAN" -eq 1 ]; then
      fresh_cas
      "$PIONC" build $FLAG --emit-obj "$BASE.o" "$SRC"
      "$CC_BIN" -fsanitize=address "$BASE.o" "$TMP_DIR/libpionrt_asan.a" -lm -lpthread -o "$BASE.asan"
      set +e
      ASAN_OPTIONS="$ASAN_OPTS" "$BASE.asan" > "$BASE.asan.out" 2> "$BASE.asan.err"
      RC=$?
      set -e
      check "$PROG $MODE ASan" "$REF" "$BASE.asan.out" "$BASE.asan.err" "$RC"
      LEGS="$LEGS + ASan"
    fi
    if [ "$HAVE_NODE" -eq 1 ]; then
      fresh_cas
      "$PIONC" build $FLAG --target wasm32 -o "$BASE.wasm" "$SRC"
      set +e
      node "$WASM_RT" "$BASE.wasm" > "$BASE.wout" 2> "$BASE.werr"
      RC=$?
      set -e
      check "$PROG $MODE Wasm32" "$REF" "$BASE.wout" "$BASE.werr" "$RC"
      LEGS="$LEGS + Wasm32"
    fi
    echo "p132 $PROG $MODE: $LEGS output equals the reference"
  done
  N=$((N + 1))
done
[ "$N" -eq 3 ]

# Divisors narrowed to 0 are a division by zero, never folded: `#verify`
# panics; plain code matches a variable divisor on the same target.
run_mode() {
  set +e
  ( exec "$1" "$2" > "$3.out" 2> "$3.err" ) 2> /dev/null
  echo $? > "$3.rc"
  set -e
}
run_wasm_mode() {
  set +e
  node "$WASM_RT" "$1" "$2" > "$3.out" 2> "$3.err"
  echo $? > "$3.rc"
  set -e
}
for MODE in dev release; do
  FLAG=""
  [ "$MODE" = "release" ] && FLAG="--release"
  BASE="$TMP_DIR/divzero_$MODE"
  fresh_cas
  "$PIONC" build $FLAG -o "$BASE" "$DIR/divzero.pion"
  LEGS="native"
  if [ "$HAVE_NODE" -eq 1 ]; then
    fresh_cas
    "$PIONC" build $FLAG --target wasm32 -o "$BASE.wasm" "$DIR/divzero.pion"
    LEGS="native wasm"
  fi
  for LEG in $LEGS; do
    for V in verify8 verify32 folded unfolded; do
      if [ "$LEG" = "native" ]; then
        run_mode "$BASE" "$V" "$BASE.$LEG.$V"
      else
        run_wasm_mode "$BASE.wasm" "$V" "$BASE.$LEG.$V"
      fi
    done
    for V in verify8 verify32; do
      R="$BASE.$LEG.$V"
      LINE=9
      [ "$V" = "verify32" ] && LINE=14
      if [ "$(cat "$R.rc")" -eq 0 ] || [ -s "$R.out" ] || ! grep -q "pion panic at divzero.pion:$LINE: division by zero" "$R.err"; then
        cat "$R.out" "$R.err" >&2
        echo "FAIL: p132 divzero $MODE $LEG $V: exit $(cat "$R.rc"), want the division-by-zero panic" >&2
        exit 1
      fi
    done
    F="$BASE.$LEG.folded"
    U="$BASE.$LEG.unfolded"
    if [ "$(cat "$F.rc")" != "$(cat "$U.rc")" ] || ! cmp -s "$F.out" "$U.out"; then
      echo "folded: exit $(cat "$F.rc"), stdout '$(cat "$F.out")'; unfolded: exit $(cat "$U.rc"), stdout '$(cat "$U.out")'" >&2
      echo "FAIL: p132 divzero $MODE $LEG: folded Int8 % 256 == 0 differs from a variable divisor" >&2
      exit 1
    fi
    echo "p132 divzero $MODE $LEG: #verify Int8 % 256 / UInt % 2^32 panic; plain == variable divisor (exit $(cat "$F.rc"))"
  done
done

# 3. `break` / `continue` outside every loop body are rejected.
mkdir -p "$TMP_DIR/neg"
cat > "$TMP_DIR/neg/body_break.pion" <<'P'
pub fn f(x : Int) -> Int {
  if x > 0 {
    break
  }
  x
}
P
cat > "$TMP_DIR/neg/body_continue.pion" <<'P'
pub fn f(x : Int) -> Int {
  match x {
    0 => continue
    _ => ()
  }
  x
}
P
cat > "$TMP_DIR/neg/while_cond_break.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut j = 0
  while j != (if j > n { break } else { 100 }) {
    j = j + 1
  }
  j
}
P
cat > "$TMP_DIR/neg/for_cond_continue.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut s = 0
  for i = 0; (if i > n { continue } else { i < 10 }); i = i + 1 {
    s = s + i
  }
  s
}
P
cat > "$TMP_DIR/neg/closure_break.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut i = 0
  while i < n {
    let g = fn(y : Int) -> Int {
      if y > 2 { break }
      y
    }
    i = i + g(i) + 1
  }
  i
}
P
cat > "$TMP_DIR/neg/for_step_break.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut s = 0
  for i = 0; i < 10; (if i > n { break } else { i = i + 1 }) {
    s = s + i
  }
  s
}
P
cat > "$TMP_DIR/neg/nested_while_cond_break.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut i = 0
  while i < n {
    i = i + 1
    let mut j = 0
    while j != (if j > i { break } else { 9 }) {
      j = j + 1
    }
  }
  i
}
P
cat > "$TMP_DIR/neg/nested_for_cond_continue.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut s = 0
  for k in 0..<n {
    for i = 0; (if i > k { continue } else { i < 3 }); i = i + 1 {
      s = s + i
    }
  }
  s
}
P
cat > "$TMP_DIR/neg/nested_for_step_continue.pion" <<'P'
pub fn f(n : Int) -> Int {
  let mut s = 0
  for k in 0..<n {
    for i = 0; i < 3; (if i > k { continue } else { i = i + 1 }) {
      s = s + i
    }
  }
  s
}
P
for NAME in body_break body_continue while_cond_break for_cond_continue closure_break for_step_break nested_while_cond_break nested_for_cond_continue nested_for_step_continue; do
  case "$NAME" in
    *continue*) KW=continue ;;
    *) KW=break ;;
  esac
  fresh_cas
  if "$PIONC" check --json "$TMP_DIR/neg/$NAME.pion" > "$TMP_DIR/neg/$NAME.json" 2>&1; then
    cat "$TMP_DIR/neg/$NAME.json" >&2
    echo "FAIL: p132 $NAME was accepted" >&2
    exit 1
  fi
  if ! grep -q '"code":"E_TYPE_MISMATCH"' "$TMP_DIR/neg/$NAME.json" ||
    ! grep -q "cannot use \`$KW\` outside a loop\"" "$TMP_DIR/neg/$NAME.json"; then
    cat "$TMP_DIR/neg/$NAME.json" >&2
    echo "FAIL: p132 $NAME: missing \"cannot use \`$KW\` outside a loop\"" >&2
    exit 1
  fi
done
fresh_cas
"$PIONC" check --json "$TMP_DIR/loops.pion" > "$TMP_DIR/loops.json" || { cat "$TMP_DIR/loops.json" >&2; echo "FAIL: p132 nested loop init / bounds / iterables rejected" >&2; exit 1; }
echo "p132 check: break / continue outside a loop body rejected (9 forms incl. nested while / for conditions and steps), init / bounds / iterables of nested loops accepted"

echo "PASS: p132_mod_pow2_loop_break"
